<div class="card"><h2>Import History</h2><div class="table-wrap"><table><thead><tr><th>Batch</th><th>File</th><th>Admin</th><th>Status</th><th>Imported</th><th>Errors</th><th></th></tr></thead><tbody><?php foreach($history as $h):?><tr><td>#<?=e($h['id'])?><div class="small"><?=e($h['uploaded_at'])?></div></td><td><?=e($h['file_name'])?></td><td><?=e($h['admin_name'])?></td><td><?=e($h['status'])?></td><td><?=e($h['imported_count'])?></td><td><span class="small"><?=nl2br(e($h['error_report']))?></span></td><td><?php if($h['status']==='imported'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="rollback"><input type="hidden" name="batch_id" value="<?=$h['id']?>"><button class="btn btn-sm btn-danger" data-confirm="Soft-delete all cases imported by this batch?">Rollback</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
